def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("input must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")

    lookup = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    result = []
    for value, numeral in lookup:
        count, n = divmod(n, value)
        result.append(numeral * count)
    return "".join(result)


_ROMAN_VALUES = {
    "I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000,
}

import re

_ROMAN_RE = re.compile(
    r"^"
    r"M{0,3}"           # thousands
    r"(CM|CD|D?C{0,3})" # hundreds
    r"(XC|XL|L?X{0,3})" # tens
    r"(IX|IV|V?I{0,3})" # ones
    r"$"
)


def from_roman(s):
    """Convert a well-formed Roman numeral string back to an integer."""
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    if not _ROMAN_RE.match(s):
        raise ValueError(f"not a valid Roman numeral: {s!r}")
    total = 0
    prev = 0
    for ch in reversed(s):
        val = _ROMAN_VALUES[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

